<?php partial('account_nav',['route'=>$route]); ?><section class="page-hero"><div><span class="eyebrow">EVERY DETAIL, IN ONE PLACE</span><h1><?= e($title) ?></h1><p><?= t('Track purchases, delivery and verified payment status here.') ?></p></div><span class="page-hero-art"><?= icon('box') ?></span></section><?php foreach ($orders as $order): ?><article class="order-card panel glass section"><header class="order-head"><span># <?= e($order['order_no']) ?></span><time><?= dt((int)$order['created_at'],'Y.m.d H:i') ?></time><span class="pill <?= e($order['status']) ?>"><?= t($order['status']) ?></span></header><div class="order-body"><span class="order-symbol"><?= icon($order['kind']==='membership'?'crown':($order['kind']==='topup'?'wallet':'box')) ?></span><div class="grow"><h3><?= e($order['title']) ?></h3><span class="muted"><?= t($order['kind']) ?> &middot; <?= t($order['fulfillment'] ?: 'Not applicable') ?></span></div><strong class="order-amount"><?= e(price((int)$order['amount'],$order['currency'])) ?></strong></div><?php if((int)$order['sale_id']>0 && $order['status']!=='paid'): ?><a class="btn secondary small" href="<?= e(url('receipt',['id'=>$order['sale_id']])) ?>"><?= t('Open checkout receipt') ?></a><?php endif ?><?php partial('shipment_link',['order'=>$order]); ?><?php partial('order_pricing' ,['order'=>$order]);partial('payment_check',['order'=>$order]); ?><?php if ($order['status']==='paid' && $order['delivery_cipher']): $delivery=$a->crypto->open($order['delivery_cipher']); ?><div class="delivery-box"><span class="eyebrow"><?= t('Delivery details') ?></span><pre><?= e($delivery) ?></pre><button class="btn secondary small" data-copy="<?= e($delivery) ?>"><?= t('Copy') ?></button></div><?php endif ?><?php if((int)$order['access_until']): ?><p class="hint"><?= t('Content access expires') ?>: <?= dt((int)$order['access_until']) ?> <?= (int)$order['access_until']<=time()?t('Expired'):'' ?></p><?php endif ?><div class="row wrap"><?php if($order['status']==='paid' && $order['fulfillment']==='shipped'): ?><?= form_start('order_receive') . hidden('order_id',$order['id']) ?><?php button('Confirm receipt','secondary small','check'); ?></form><?php endif ?><?php if (in_array($order['kind'],['content','circle'],true) && $order['status']==='paid'): ?><a class="btn secondary small" href="<?= e(url($order['kind']==='circle'?'circle':'article',['id'=>$order['item_id']])) ?>"><?= t($order['kind']==='circle'?'Open circle':'Open your content') ?><?= icon('arrow') ?></a><?php if((int)$order['sale_id']>0): ?><a class="btn secondary small" href="<?= e(url('receipt',['id'=>$order['sale_id']])) ?>"><?= t('Receipt and after-sales') ?></a><?php else: ?><details class="grow"><summary><?= t('Request a refund') ?></summary><?= form_start('refund') . hidden('order_id',$order['id']) ?><?php field('reason','Refund reason','','textarea',['required'=>'required','maxlength'=>'1000']);button('Submit request','secondary small','message'); ?></form></details><?php endif ?><?php endif ?><?php if ($order['kind']==='topup' && $order['status']==='pending'): ?><a class="btn small" href="<?= e(url('pay',['id'=>$order['id']])) ?>"><?= t('Continue payment') ?><?= icon('arrow') ?></a><a class="btn secondary small" href="<?= e(url('orders',['id'=>$order['id']])) ?>"><?= icon('refresh') ?><?= t('Refresh status') ?></a><?php endif ?></div><?php if ($order['kind']==='topup' && $order['status']!=='paid'): ?><p class="hint"><?= t('The payment provider callback is the source of truth. Contact the site if a completed payment remains pending.') ?></p><?php endif ?></article><?php endforeach ?><?php if (!$orders) {empty_state('No orders yet. Something good will find you.','box');} ?><?php partial('pagination',['pagination'=>$pagination,'route'=>$route]); ?>
